<template><section aria-label="ASCII 艺术字生成"><p class="tool-note">本地 5×7 点阵艺术字，支持英文字母、数字与常用标点；小写转大写，中文等未覆盖字符以问号绘制并提示。最多 200 个字符，支持换行。</p><label class="tool-label">艺术字原文<textarea v-model="input" maxlength="200" aria-label="艺术字原文" spellcheck="false" rows="3"></textarea></label><div class="tool-actions ascii-settings"><label>艺术字样式<select v-model="style"><option value="standard">标准</option><option value="wide">加宽</option><option value="slant">斜体</option></select></label><label>绘制符号<input v-model="ink" aria-label="绘制符号" maxlength="1" /></label><label>字间距<select v-model.number="spacing"><option v-for="n in 5" :key="n" :value="n-1">{{n-1}} 格</option></select></label></div><p v-if="error" class="tool-error" role="alert">{{error}}</p><p v-if="rendered.unsupported.length" class="tool-note" role="status">未覆盖字符：{{rendered.unsupported.join('、')}}，已替换为问号。</p><label class="tool-label">艺术字预览<textarea class="ascii-output" :value="rendered.text" readonly aria-label="艺术字预览" spellcheck="false" wrap="off"></textarea></label><div class="tool-actions"><button type="button" :disabled="!rendered.text" @click="copy">复制艺术字</button><button type="button" :disabled="!rendered.text" @click="download">下载艺术字 TXT</button><button type="button" @click="input='';message=''">清空艺术字</button></div><p role="status">{{message}}</p></section></template>
<script>
import {asciiArt} from '../../utils/ascii-art.mjs';
import {downloadBlob} from '../../utils/utility-tools.mjs';
export default{name:'AsciiArtTool',data:()=>({input:'HELLO WORLD',style:'standard',ink:'#',spacing:1,message:''}),computed:{error(){try{asciiArt(this.input,{style:this.style,ink:this.ink,spacing:this.spacing});return '';}catch(e){return e.message;}},rendered(){if(this.error)return {text:'',unsupported:[]};return asciiArt(this.input,{style:this.style,ink:this.ink,spacing:this.spacing});}},methods:{async copy(){try{await navigator.clipboard.writeText(this.rendered.text);this.message='艺术字已复制';}catch{this.message='请选中预览内容手动复制';}},download(){downloadBlob(new Blob([this.rendered.text],{type:'text/plain;charset=utf-8'}),'ascii-art.txt');this.message='已生成 TXT 下载';}}};
</script>
<style scoped>
.ascii-settings{align-items:flex-end}.ascii-settings label{display:flex;flex-direction:column;gap:6px;min-width:100px;font-size:12px}.ascii-settings input{max-width:100px}.ascii-output{width:100%;min-height:230px;resize:vertical;white-space:pre;overflow:auto;font-family:ui-monospace,SFMono-Regular,Consolas,monospace!important;font-size:12px!important;line-height:1.35!important;letter-spacing:0!important;font-variant-ligatures:none}
</style>
